class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        M = max(nums)
        pos = [i for i, x in enumerate(nums) if x == M]
        total = 0
        c = 0
        for r in range(len(nums)):
            if nums[r] == M:
                c += 1
            if c >= k:
                total += pos[c - k] + 1
        return total
