class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        M = max(nums)
        pos = [i for i, x in enumerate(nums) if x == M]
        m = len(pos)
        total = 0
        for j in range(k - 1, m):
            left_bound = pos[j - k + 1]
            prev = pos[j - k] if j - k >= 0 else -1
            total += (left_bound - prev) * (n - pos[j])
        return total
