class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        M = max(nums)
        pos = [i for i, x in enumerate(nums) if x == M]
        m = len(pos)
        total = 0
        for c in range(m):
            idx = c - k + 1
            if idx < 0:
                continue
            end_count = (pos[c + 1] if c + 1 < m else n) - pos[c]
            total += end_count * (pos[idx] + 1)
        return total

