import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 8))
    mode = draw(st.integers(0, 4))
    if mode == 0:
        # all equal elements
        v = draw(st.integers(1, 5))
        nums = [v] * n
    elif mode == 1:
        # sorted ascending with duplicates
        nums = sorted(draw(st.lists(st.integers(1, 5), min_size=n, max_size=n)))
    elif mode == 2:
        # sorted descending
        nums = sorted(draw(st.lists(st.integers(1, 5), min_size=n, max_size=n)), reverse=True)
    else:
        nums = draw(st.lists(st.integers(1, 5), min_size=n, max_size=n))
    k = draw(st.integers(1, min(n + 1, 9)))
    return f"{json.dumps(nums)}\n{k}\n"

def validate(inp):
    lines = inp.split("\n")
    if len(lines) != 3 or lines[2] != "":
        return False
    try:
        nums = json.loads(lines[0])
        k = json.loads(lines[1])
    except Exception:
        return False
    if not isinstance(nums, list) or not isinstance(k, int) or isinstance(k, bool):
        return False
    if not (1 <= len(nums) <= 10**5):
        return False
    if not all(isinstance(x, int) and not isinstance(x, bool) and 1 <= x <= 10**6 for x in nums):
        return False
    if not (1 <= k <= 10**5):
        return False
    return True

def ref(inp):
    lines = inp.split("\n")
    nums = json.loads(lines[0])
    k = json.loads(lines[1])
    n = len(nums)
    count = 0
    for i in range(n):
        for j in range(i, n):
            sub = nums[i:j + 1]
            m = max(sub)
            if sub.count(m) >= k:
                count += 1
    return json.dumps(count)
